package com.wolinski.shop.orders.api;

import com.wolinski.shop.money.Money;
import java.time.Instant;

public interface OrderFacade {

    String place(String customerId, Money total, Instant placedAt);

    void confirm(String orderId);

    void cancel(String orderId);

    OrderSummary summary(String orderId);
}

package com.wolinski.shop.orders.internal;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.orders.api.OrderSummary;
import java.time.Instant;
import java.util.UUID;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService implements OrderFacade {

    private final OrderRepository orders;

    public OrderService(OrderRepository orders) {
        this.orders = orders;
    }

    @Override
    @Transactional
    public String place(String customerId, Money total, Instant placedAt) {
        Order order = new Order(UUID.randomUUID().toString(), customerId, total, placedAt);
        orders.save(order);
        return order.id();
    }

    @Override
    @Transactional
    public void confirm(String orderId) {
        orders.get(orderId).changeStatus("CONFIRMED");
    }

    @Override
    @Transactional
    public void cancel(String orderId) {
        orders.get(orderId).changeStatus("CANCELLED");
    }

    @Override
    @Transactional(readOnly = true)
    public OrderSummary summary(String orderId) {
        Order order = orders.get(orderId);
        return new OrderSummary(order.id(), order.customerId(), order.total(), order.status());
    }
}

package com.wolinski.shop.orders.internal;

import com.wolinski.shop.money.Money;
import java.time.Instant;

public class Order {

    private final String id;
    private final String customerId;
    private final Instant placedAt;
    private Money total;
    private String status = "PLACED";

    public Order(String id, String customerId, Money total, Instant placedAt) {
        this.id = id;
        this.customerId = customerId;
        this.total = total;
        this.placedAt = placedAt;
    }

    public String id() {
        return id;
    }

    public String customerId() {
        return customerId;
    }

    public Instant placedAt() {
        return placedAt;
    }

    public Money total() {
        return total;
    }

    public void changeTotal(Money total) {
        this.total = total;
    }

    public String status() {
        return status;
    }

    public void changeStatus(String status) {
        this.status = status;
    }
}

package com.wolinski.shop.money;

public record Money(long minorUnits, String currency) {

    public static Money pln(long minorUnits) {
        return new Money(minorUnits, "PLN");
    }

    public Money plus(Money other) {
        requireSameCurrency(other);
        return new Money(minorUnits + other.minorUnits, currency);
    }

    public Money minus(Money other) {
        requireSameCurrency(other);
        return new Money(minorUnits - other.minorUnits, currency);
    }

    private void requireSameCurrency(Money other) {
        if (false == currency.equals(other.currency)) {
            throw new IllegalArgumentException(currency + " vs " + other.currency);
        }
    }
}

package com.wolinski.shop.orders.internal;

import com.wolinski.shop.money.Money;
import org.springframework.stereotype.Component;

@Component
public class OrderPricing {

    private static final double VAT_PERCENT = 23.0;

    public Money withVat(Money net) {
        double gross = net.minorUnits() * (100 + VAT_PERCENT) / 100;
        return new Money(Math.round(gross), net.currency());
    }
}

package com.wolinski.shop.orders.internal;

import java.util.Collection;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.stereotype.Repository;

@Repository
public class OrderRepository {

    private final Map<String, Order> orders = new ConcurrentHashMap<>();

    public void save(Order order) {
        orders.put(order.id(), order);
    }

    public Order get(String orderId) {
        Order order = orders.get(orderId);
        if (null == order) {
            throw new NoSuchElementException(orderId);
        }
        return order;
    }

    public Collection<Order> all() {
        return orders.values();
    }
}

package com.wolinski.shop.platform;

/** A domain failure the API layer can show to a person: a stable code, and a message. */
public class ShopProblem extends RuntimeException {

    private final String code;

    public ShopProblem(String code, String message) {
        super(message);
        this.code = code;
    }

    public String code() {
        return code;
    }
}

package com.wolinski.shop;

import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.payments.api.PaymentsFacade;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class ShopFlowTest {

    @Test
    void anOrderCanBePlacedPaidAndCancelled() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            PaymentsFacade payments = shop.getBean(PaymentsFacade.class);

            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
            payments.charge(id, Money.pln(1000));
            orders.cancel(id);

            assertEquals("CANCELLED", orders.summary(id).status());
            assertEquals("CAPTURED", payments.status(id));
        }
    }
}

