import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;

/** Turns a percentage typed into a form into basis points, and a basis-point rate into an amount. */
final class Discount {

    private static final long WHOLE_RATE = 10_000;
    private static final long MAX_BASIS_POINTS = 100 * 100;

    private Discount() {
    }

    /**
     * Parses text such as "12.5" or "12" into whole basis points (12.5% is 1250).
     * At most two decimal places are accepted, and the value must be between 0 and 100 inclusive.
     */
    static long basisPointsOf(String text) {
        String s = null == text ? "" : text.trim();
        int dot = s.indexOf('.');
        String whole = dot < 0 ? s : s.substring(0, dot);
        String fraction = dot < 0 ? "" : s.substring(dot + 1);

        boolean wellFormed = isDigits(whole)
                && (dot < 0 || (isDigits(fraction) && fraction.length() <= 2));
        if (!wellFormed) {
            throw new ShopProblem("DISCOUNT_PERCENT_INVALID",
                    "Discount must be a percentage such as 12 or 12.5, with at most two decimals: " + text);
        }
        if (whole.length() > 3) {
            throw outOfRange(text);
        }

        long basisPoints = Long.parseLong(whole) * 100;
        if (fraction.length() == 1) {
            basisPoints += Long.parseLong(fraction) * 10;
        } else if (fraction.length() == 2) {
            basisPoints += Long.parseLong(fraction);
        }
        if (basisPoints > MAX_BASIS_POINTS) {
            throw outOfRange(text);
        }
        return basisPoints;
    }

    /** The discount on {@code total} at {@code basisPoints}, rounded half up to a minor unit. */
    static Money amountOf(Money total, long basisPoints) {
        long product = Math.multiplyExact(total.minorUnits(), basisPoints);
        long minorUnits = Math.floorDiv(Math.addExact(product, WHOLE_RATE / 2), WHOLE_RATE);
        return new Money(minorUnits, total.currency());
    }

    private static boolean isDigits(String s) {
        if (s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static ShopProblem outOfRange(String text) {
        return new ShopProblem("DISCOUNT_PERCENT_OUT_OF_RANGE",
                "Discount must be between 0 and 100 percent: " + text);
    }
}
}

