{path=src/test/java/com/wolinski/shop/OrderDiscountTest.java, content=package com.wolinski.shop;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.platform.ShopProblem;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class OrderDiscountTest {

    private static final Instant NOW = Instant.parse("2026-10-01T10:00:00Z");

    @Test
    void aDiscountLowersTheTotalAndRoundsHalfUp() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);

            String id = orders.place("c-1", Money.pln(100), NOW);
            orders.applyDiscount(id, "0.5");
            assertEquals(Money.pln(99), orders.summary(id).total());
        }
    }

    @Test
    void aWholeDiscountIsExact() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);

            String id = orders.place("c-1", Money.pln(20000), NOW);
            orders.applyDiscount(id, "12.5");
            assertEquals(Money.pln(17500), orders.summary(id).total());
        }
    }

    @Test
    void halfACentRoundsUp() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);

            String id = orders.place("c-1", Money.pln(1), NOW);
            orders.applyDiscount(id, "50");
            assertEquals(Money.pln(0), orders.summary(id).total());
        }
    }

    @Test
    void aHundredPercentDiscountClearsTheTotal() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);

            String id = orders.place("c-1", Money.pln(1234), NOW);
            orders.applyDiscount(id, "100.00");
            assertEquals(Money.pln(0), orders.summary(id).total());
        }
    }

    @Test
    void badPercentagesAreRefusedWithAShopProblem() {
        try (var shop = new AnnotationConfigApplicationContext(ShopConfig.class)) {
            OrderFacade orders = shop.getBean(OrderFacade.class);
            String id = orders.place("c-1", Money.pln(1000), NOW);

            for (String bad : new String[] {"", "abc", "-1", "12,5", "1.234", "12.", ".5", "100.01", "101", "1e1"}) {
                ShopProblem problem = assertThrows(ShopProblem.class, () -> orders.applyDiscount(id, bad), bad);
                assertEquals(true, problem.code().startsWith("DISCOUNT_PERCENT_"), bad);
            }
            assertEquals(Money.pln(1000), orders.summary(id).total());
        }
    }
}
}
